cssCode:
.skeleton-wrap {
  width: 280px;
  display: flex; flex-direction: column; gap: 15px;
}
.skeleton-box {
  height: 20px;
  border-radius: 10px;
  background: #222;
  background-image: linear-gradient(90deg, #222 0px, #333 40px, #222 80px);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite linear;
}
.skeleton-box:nth-child(1) { height: 150px; border-radius: 15px; }
.skeleton-box:nth-child(2) { width: 80%; }
.skeleton-box:nth-child(3) { width: 60%; }

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'skeleton-wrap';

for(let i=0; i<3; i++){
  const box = document.createElement('div');
  box.className = 'skeleton-box';
  wrap.appendChild(box);
}

c.appendChild(wrap);
